import { useState } from 'react';
import '../../styles/tokens.css';
import { Button } from '../../components/Button.jsx';
import { Switch } from './Switch.jsx';
import './notification-settings.css';

export function NotificationSettings({ initialEmail = true, initialPush = false, onSave }) {
  const [email, setEmail] = useState(initialEmail);
  const [push, setPush] = useState(initialPush);
  const [saved, setSaved] = useState(false);

  const update = (setter) => (value) => { setter(value); setSaved(false); };

  const handleSave = async () => {
    await onSave?.({ email, push });
    setSaved(true);
  };

  return (
    <main className="notification-settings">
      <h1 className="notification-settings__title">Notifications</h1>
      <Switch Label="Email notifications" checked={email} onChange={update(setEmail)} />
      <Switch Label="Push notifications" checked={push} onChange={update(setPush)} />
      <Button Label="Save" onClick={handleSave} />
      <p className="notification-settings__status" role="status">{saved ? 'Settings saved' : ''}</p>
    </main>
  );
}

