import { useState } from 'react';
import { Field } from './Field';
import { Chip } from './Chip';
import { Tag } from './Tag';
import { Button } from './Button';
import './search-header.css';

const RANGES = ['Today', 'This week', 'This month'];

export function SearchHeader({ onSearch }) {
  const [query, setQuery] = useState('');
  const [range, setRange] = useState(null);

  function handleSubmit(event) {
    event.preventDefault();
    onSearch?.({ query, range });
  }

  return (
    <form role="search" className="search-header" onSubmit={handleSubmit}>
      <Field label="Search" type="search" placeholder="Search" onChange={(e) => setQuery(e.target.value)} />
      <div className="search-header__filters" role="group" aria-label="Date range">
        {RANGES.map((name, i) => (
          <span key={name} className="search-header__filter">
            <Chip Label={name} pressed={range === name} onClick={() => setRange(range === name ? null : name)} />
            {i === 0 && <Tag Label="New" />}
          </span>
        ))}
      </div>
      <Button Label="Search" type="submit" />
    </form>
  );
}

